int input_fd = 0; // File Descriptor (e.g., STDIN_FILENO)
char data_buffer[512];
size_t requested_bytes = sizeof(data_buffer);

// ssize_t read(int fd, void *buf, size_t count);
ssize_t result = read(
    input_fd,
    data_buffer,
    requested_bytes
);

// Return Codes:
// result > 0 : Number of bytes read successfully
// result == 0: End Of File (EOF) reached
// result == -1: Error occurred (check errno)
